fn main(){
    let n = ::vox::morphism_factor::parse_numeral(N_WORD).expect("baked word must parse");
    println!("baked N word: {} glyphs; N = {}", N_WORD.chars().count(), ::vox::morphism_factor::dec_of(&n));
    match ::vox::morphism_factor::factor(N_WORD) {
        Ok(w) => { let f = ::vox::morphism_factor::parse_numeral(&w).unwrap(); println!("FACTOR WORD: {}", w); println!("FACTOR(decoded): {}", ::vox::morphism_factor::dec_of(&f)); }
        Err(e) => println!("refused: {}", e),
    }
}
